package org.sebastiandev.trip.payment.messaging; import com.fasterxml.jackson.databind.ObjectMapper; import io.smallrye.mutiny.Uni; import jakarta.enterprise.context.ApplicationScoped; import jakarta.inject.Inject; import java.time.*; import java.util.UUID; import org.sebastiandev.trip.contracts.event.*; import org.sebastiandev.trip.contracts.observability.*; import org.sebastiandev.trip.payment.repository.OutboxRepository;
@ApplicationScoped public class OutboxService{@Inject ObjectMapper mapper;@Inject OutboxRepository repository;public Uni<EventEnvelope> enqueue(String topic,UUID id,UUID cause,Object payload){EventEnvelope env=EventCodec.envelope(mapper,topic,id,cause,"payment-service",payload);OutboxEvent event=new OutboxEvent();event.id=env.eventId();event.topic=topic;event.aggregateId=id;event.payload=EventCodec.encode(mapper,env);TraceContextSnapshot trace=TraceContextSupport.captureCurrent();event.traceParent=trace.traceParent();event.traceState=trace.traceState();event.createdAt=OffsetDateTime.now(ZoneOffset.UTC);return repository.persist(event).replaceWith(env);}}
